    /** 解析商店结果 */
    function parseShopResult(raw) {
        const items = [];
        const lineRegex = /^(?:([^|｜]+?)\s*[|｜]\s*)?(.+?)\s*[|｜]\s*(.+?)\s*[|｜]\s*(.+?)\s*[|｜]\s*(\d+)\s*(?:[|｜]\s*(.+?)\s*)?$/;
        for (const line of raw
            .split(/\n/)
            .map(s => s.trim())
            .filter(Boolean)) {
            const m = line.match(lineRegex);
            if (!m)
                continue;
            const rawId = (m[1] ?? '').trim();
            const name = (m[2] ?? '').trim();
            const icon = (m[3] ?? '').trim();
            const effect = (m[4] ?? '').trim();
            const price = Number((m[5] ?? '').trim());
            const tagsRaw = (m[6] ?? '').trim();
            const tags = tagsRaw
                ? tagsRaw
                    .split(/[,，\s]+/)
                    .map(s => s.trim())
                    .filter(Boolean)
                : undefined;
            items.push({
                id: rawId || `s${Date.now()}_${items.length}`,
                name,
                icon: icon || undefined,
                effect,
                price: Number.isFinite(price) ? price : 0,
                tags,
            });
        }
        if (items.length === 0) {
            try {
                const parsed = JSON.parse(raw);
                if (Array.isArray(parsed))
                    parsed.forEach((p2, i) => items.push({
                        id: p2.id || `s${Date.now()}_${i}`,
                        name: p2.name ?? '',
                        icon: p2.icon,
                        effect: p2.effect ?? '',
                        price: Number(p2.price) || 0,
                        tags: Array.isArray(p2.tags) ? p2.tags : undefined,
                    }));
            }
            catch {
                /* ignore */
            }
        }
        return items;
    }
