    const currentFloorDanmaku = ref([]);
    // 循环播放定时器
    let danmakuLoopTimer = null;
    // 弹幕生成定时器（用于控制密度）
    let danmakuSpawnTimer = null;
    let _danmakuIdCounter = 0;
