            if (riddleAnswerContains(userText)) {
                showToast('输入中包含谜底，已拦截');
                return '';
            }
            const ok = addRiddleUserMessage(userText);
            if (!ok) {
                showToast('输入中包含谜底，已拦截');
                return '';
            }
