                    const idx = hist.findLastIndex(m => m.role === 'riddle_end_pending');
                    if (idx >= 0)
                        hist[idx] = { role: 'riddle_end', text: '' };
                    // 在猜谜结束后追加一条分割线，与下一段普通聊天分隔
                    hist.splice(idx + 1, 0, { role: 'riddle_divider', text: '' });
