lay:flex;align-items:center;gap:5px;font-size:10px;color:var(--theme-text-muted,var(--vn-muted));padding-bottom:6px;border-bottom:1px solid rgba(90,79,64,0.1)}.im-skill-hint i[data-v-77c3316c]{color:var(--theme-accent,var(--rust));font-size:10px}.im-skill-card[data-v-77c3316c]{padding:10px;background:rgba(74,64,53,0.08);border:1px solid rgba(90,79,64,0.25);border-radius:2px;display:flex;flex-direction:column;gap:6px}.im-skill-header[data-v-77c3316c]{display:flex;align-items:flex-start;gap:8px}.im-skill-avatar[data-v-77c3316c]{width:36px;height:36px;display:flex;align-items:center;justify-content:center;background:rgba(139,69,19,0.15);border:1px solid rgba(139,69,19,0.3);border-radius:2px;flex-shrink:0}.im-skill-emoji[data-v-77c3316c]{font-size:1.3rem}.im-skill-meta[data-v-77c3316c]{flex:1;min-width:0}.im-skill-name[data-v-77c3316c]{font-size:12px;font-weight:bold;color:var(--theme-text-main,rgba(212,197,160,0.92));margin-bottom:3px}.im-skill-mods[data-v-77c3316c]{display:flex;flex-wrap:wrap;gap:3px}.im-mod-chip[data-v-77c3316c]{font-size:8px;padding:1px 5px;background:rgba(139,69,19,0.15);border:1px solid rgba(139,69,19,0.3);color:var(--theme-accent,var(--rust));border-radius:2px;font-family:monospace}.im-skill-desc[data-v-77c3316c]{font-size:10px;color:var(--theme-text-muted,var(--vn-muted));line-height:1.5}.im-skill-equipped[data-v-77c3316c]{font-size:10px;color:var(--vn-success)}.im-skill-equipped i[data-v-77c3316c]{margin-right:4px}.im-skill-not-equipped[data-v-77c3316c]{font-size:10px;color:var(--theme-text-muted,var(--vn-muted))}.im-skill-not-equipped i[data-v-77c3316c]{margin-right:4px}
